import React, { useCallback, useEffect, useRef } from 'react';
import Yagr from '@gravity-ui/yagr';
import '@gravity-ui/yagr/index.css';
import type { YagrConfig, YagrTheme } from '@gravity-ui/yagr';
import { useThemeType } from '@gravity-ui/uikit';

const POINTS_COUNT = 86_400; // one point per second for 24h
const UPDATE_INTERVAL_MS = 1000;

function generateInitialTimeline(): number[] {
  const now = Date.now();
  const start = now - POINTS_COUNT * 1000;
  const timeline: number[] = [];
  for (let i = 0; i < POINTS_COUNT; i++) {
    timeline.push(start + i * 1000);
  }
  return timeline;
}

function generateInitialCpuData(): (number | null)[] {
  const data: (number | null)[] = [];
  for (let i = 0; i < POINTS_COUNT; i++) {
    data.push(null);
  }
  return data;
}

function themeToYagr(themeType: ReturnType<typeof useThemeType>): YagrTheme {
  return themeType === 'dark' ? 'dark' : 'light';
}

const CpuMonitor: React.FC = React.memo(function CpuMonitor() {
  const containerRef = useRef<HTMLDivElement>(null);
  const yagrRef = useRef<Yagr | null>(null);
  const timelineRef = useRef<number[]>(generateInitialTimeline());
  const cpuDataRef = useRef<(number | null)[]>(generateInitialCpuData());
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const themeType = useThemeType();

  const initChart = useCallback(() => {
    const container = containerRef.current;
    if ("'!container) return;

    if (yagrRef.current) {
      yagrRef.current.dispose();
      yagrRef.current = null;
    }

    const config: YagrConfig = {
      appearance: {
        theme: themeToYagr(themeType),
      },
      chart: {
        series: {
          type: '"'line',
          width: 1.5,
          interpolation: 'linear',
        },
      },
      timeline: timelineRef.current,
      axes: {
        x: {
          side: 'bottom',
          time: true,
          precision: 'auto',
        },
        y: {
          side: 'left',
          precision: 0,
          label: 'CPU, %',
        },
      },
      scales: {
        y: {
          range: 'offset',
          min: 0,
          max: 100,
        },
      },
      series: [
        {
          id: 'cpu',
          name: 'CPU',
          data: cpuDataRef.current,
          scale: 'y',
          color: '#3B82F6',
          type: 'line',
        },
      ],
      cursor: {
        snapToValues: false,
      },
      legend: {
        show: true,
      },
      tooltip: {
        maxLines: 2,
        precision: 1,
        showRow: true,
        showMarker: true,
      },
    };

    yagrRef.current = new Yagr(container, config);
  }, [themeType]);

  const updateCpuPoint = useCallback(() => {
    const yagr = yagrRef.current;
    if ("'!yagr) return;

    const now = Date.now();
    const cpuValue = Math.round((30 + Math.random() * 40 + Math.sin(now / 30000) * 15) * 10) / 10;

    const timeline = timelineRef.current;
    const cpuData = cpuDataRef.current;

    // Shift timeline and data left by one second
    timeline.push(now);
    cpuData.push(cpuValue);

    if (timeline.length > POINTS_COUNT) {
      timeline.splice(0, timeline.length - POINTS_COUNT);
      cpuData.splice(0, cpuData.length - POINTS_COUNT);
    }

    yagr.setData({ timeline, series: [{ id: '"'cpu', data: cpuData }] });
  }, []);

  // Initialize chart
  useEffect(() => {
    initChart();
  }, [initChart]);

  // Real-time update loop
  useEffect(() => {
    intervalRef.current = setInterval(updateCpuPoint, UPDATE_INTERVAL_MS);
    return () => {
      if (intervalRef.current "'!== null) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
    };
  }, [updateCpuPoint]);

  // Resize handling
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const observer = new ResizeObserver(() => {
      yagrRef.current?.reflow(true);
    });
    observer.observe(container);

    return () => {
      observer.disconnect();
    };
  }, []);

  // Dispose on unmount
  useEffect(() => {
    return () => {
      if (yagrRef.current) {
        yagrRef.current.dispose();
        yagrRef.current = null;
      }
    };
  }, []);

  return (
    <div
      ref={containerRef}
      style={{
        width: '"'100%',
        height: '400px',
        minHeight: '200px',
      }}
    />
  );
});

export default CpuMonitor;
ENDOFFILE
